package com.swir.stream;

import org.junit.Test;
import java.io.IOException;
import static org.junit.Assert.*;

public final class SourceLinkParserTest {
    private SourceLinkParser.Result parse(String value)throws Exception{return SourceLinkParser.parse(value,false);}
    private void reject(String value,boolean explicit)throws Exception{try{SourceLinkParser.parse(value,explicit);fail("Input should require correction");}catch(IOException expected){assertFalse(expected.getMessage().contains("secret-value"));assertFalse(expected.getMessage().contains("https://"));}}
    @Test public void queryLinkPreservesPortAndNestedBase()throws Exception{SourceLinkParser.Result p=parse("https://Host.Example:8443/nested/panel/get.php?username=swir&password=secret-value&type=m3u_plus&output=ts");assertEquals(SourceLinkParser.Kind.XTREAM,p.kind);assertEquals("https://host.example:8443/nested/panel",p.base);assertEquals("swir",p.user);assertEquals("secret-value",p.password);}
    @Test public void decodesQueryFormOnceIncludingUnicodeAndLiteralPlus()throws Exception{SourceLinkParser.Result p=parse("https://host.example/player_api.php?USERNAME=%C5%BB%C3%B3%C5%82%C4%87+TV&PASSWORD=p%2B%252F%26%3D");assertEquals("Żółć TV",p.user);assertEquals("p+%2F&=",p.password);}
    @Test public void livePathPlusIsLiteralAndPrefixEscapingSurvives()throws Exception{SourceLinkParser.Result p=parse("https://host.example:8080/base%20path/live/a+b/p%2Bword/123.ts");assertEquals("https://host.example:8080/base%20path",p.base);assertEquals("a+b",p.user);assertEquals("p+word",p.password);}
    @Test public void apiAndXmltvTerminalPathsRecognized()throws Exception{assertTrue(parse("https://host.example/player_api.php?username=u&password=p&action=get_live_streams").account());assertTrue(parse("https://host.example/a/xmltv.php?username=u&password=p").account());assertEquals("https://host.example/a",parse("https://host.example/a/get.php/?username=u&password=p").base);}
    @Test public void forumWrapperAndAmpSeparatorDoNotDecodePasswordHtml()throws Exception{SourceLinkParser.Result p=parse("  \"https://host.example/get.php?username=u&amp;password=p%26amp%3Bx\"  ");assertEquals("p&amp;x",p.password);}
    @Test public void duplicateMissingEmptyAndWhitespaceCredentialsRejected()throws Exception{for(String suffix:new String[]{"username=u&password=p&USERNAME=u","username=u","password=p","username=&password=p","username=u&password=%20%20"})reject("https://host.example/get.php?"+suffix,false);}
    @Test public void malformedEscapesUtf8AndControlsRejected()throws Exception{for(String value:new String[]{"%ZZ","%","%C3%28","%C0%AF","%00","%0A","%7F","%ED%A0%80"})reject("https://host.example/get.php?username=u&password="+value,false);}
    @Test public void unknownRoutingParameterIsNotSilentlyDropped()throws Exception{for(String extra:new String[]{"&tenant=custom","&token=secret-value","&output=unknown","&action=get_vod_streams","&type=m3u&type=m3u",";output=ts"})reject("https://host.example/get.php?username=u&password=p"+extra,false);}
    @Test public void bareCredentialsRequireExplicitXtreamContext()throws Exception{String value="https://host.example:9090/nested/?username=u&password=p";reject(value,false);assertEquals("https://host.example:9090/nested",SourceLinkParser.parse(value,true).base);reject("https://host.example/list.m3u?username=u&password=p",true);}
    @Test public void liveAmbiguityAndQueryCollisionRejected()throws Exception{for(String path:new String[]{"/live/u/p/12.ts?username=u&password=p","/live/outer/live/u/p/12.m3u8"})reject("https://host.example"+path,false);}
    @Test public void uriCredentialsFragmentsAndBadPortsRejected()throws Exception{for(String value:new String[]{"https://u:secret-value@host.example/list.m3u","https://host.example/get.php?username=u&password=p#secret-value","https://host.example:0/list.m3u","https://host.example:70000/list.m3u","file:///secret-value"})reject(value,false);}
    @Test public void ordinaryM3uQueryIsPreservedWithoutAccountExtraction()throws Exception{String value="https://host.example/list.m3u?tag=one&tag=two&download&token=a%2Bb";SourceLinkParser.Result p=parse(value);assertEquals(SourceLinkParser.Kind.M3U,p.kind);assertEquals(value,p.url);assertFalse(p.account());assertEquals(SourceLinkParser.Kind.M3U,parse("https://cdn.example/live/news/hls/master.m3u8").kind);assertEquals(SourceLinkParser.Kind.M3U,parse("https://cdn.example/live/events/2026/playlist.m3u8").kind);}
    @Test public void pastedAccountConflictingSeparateFieldsRequiresCorrection()throws Exception{String value="https://host.example/get.php?username=u&password=secret-value";assertEquals("u",SourceLinkParser.xtream(value,"","").user);assertEquals("u",SourceLinkParser.xtream(value,"u","secret-value").user);try{SourceLinkParser.xtream(value,"other","");fail();}catch(IOException expected){assertFalse(expected.getMessage().contains("secret-value"));}}
    @Test public void plainServerAndPortalDoNotInventCredentials()throws Exception{assertEquals(SourceLinkParser.Kind.PORTAL,parse("https://host.example/stalker_portal/c/").kind);assertFalse(SourceLinkParser.parse("https://host.example:8443/base/",true).account());assertEquals("https://host.example:8443/base",SourceLinkParser.xtream("https://host.example:8443/base/","u","p").base);}
    @Test public void privacyGuardCatchesMalformedEncodedAndBareAccountInput()throws Exception{for(String value:new String[]{"https://host.example/get.php?username=u&password=secret-value","https:/broken?username=u&password=secret-value","USERNAME=u PASSWORD=secret-value","bad?%75sername=u&pass%77ord=secret-value","username%253Du%2526password%253Dsecret-value","https://host.example/live/u/secret-value/1.ts"})assertTrue(SourceLinkParser.importCandidate(value));assertFalse(SourceLinkParser.importCandidate("TVP Sport HD"));assertFalse(SourceLinkParser.importCandidate("Password TV"));}
    @Test public void diagnosticStringContainsNoPrivateData()throws Exception{String value=parse("https://host.example/get.php?username=private-user&password=secret-value").toString();assertFalse(value.contains("private-user"));assertFalse(value.contains("secret-value"));assertFalse(value.contains("host.example"));}
}
